"""webserverDAT callbacks -- serves live state JSON for the local
push2_live_overlay.html page (not the published claude.ai artifact, which
cannot reach localhost). GET /state -> full snapshot."""
from typing import Dict, Any
import json


def _snapshot():
	ext = op('/project1/PUSH_RESOLUME')
	out = {
		'armed': ext.Armed,
		'health': dict(ext.Health),
		'gridMode': ext.Surface.GridMode if ext.Surface else None,
		'bank': ext.Surface.Bank if ext.Surface else None,
		'modifiers': list(ext.Surface.Modifiers) if ext.Surface else [],
		'fx': {},
		'clips': {},
		'encoders': dict(ext.Surface.EncoderValues) if ext.Surface else {},
	}
	if ext.FxRegistry:
		for key, e in ext.FxRegistry.Registry.items():
			out['fx'][key] = {
				'label': e.get('label'), 'onValue': e.get('on_value'),
				'bypassed': bool(e.get('bypassed_value')),
				'padOn': bool(e.get('_padOn')),
			}
	if ext.ResolumeState:
		for (layer, clip), c in ext.ResolumeState.Clips.items():
			out['clips']['%s:%d' % (layer, clip)] = bool(c.get('connected'))
	return out


def onHTTPRequest(dat: webserverDAT, request: Dict[str, Any],
                   response: Dict[str, Any]) -> Dict[str, Any]:
	response['Access-Control-Allow-Origin'] = '*'
	if request.get('uri') == '/state':
		try:
			body = json.dumps(_snapshot())
			response['statusCode'] = 200
			response['statusReason'] = 'OK'
			response['content-type'] = 'application/json'
			response['data'] = body
		except Exception as e:
			response['statusCode'] = 500
			response['statusReason'] = 'Error'
			response['content-type'] = 'application/json'
			response['data'] = json.dumps({'error': str(e)})
		return response
	response['statusCode'] = 404
	response['statusReason'] = 'Not Found'
	response['data'] = 'Use /state'
	return response


