dats./project1/PUSH_RESOLUME/logic/mod_surfac:
"""Surface: the state machine. Resolves (in_type, number, modifier, grid_mode)
tuples to map_controls rows, tracks modifiers/grid mode/bank/encoders, and
emits intents. Emits intents only; sends nothing itself (DESIGN.md 2.3)."""

import re

_COLS = ['id', 'zone', 'in_type', 'in_number', 'in_channel', 'modifier',
         'grid_mode', 'action', 'target', 'slot', 'transport', 'control_path',
         'value_type', 'value', 'led_state_source', 'led_palette', 'notes']

_LAYER_TARGETS = {'LAYER1': 'L1', 'LAYER2': 'L2', 'LAYER3': 'L3'}

_TOKEN_RE = re.compile(r'\{([^{}]+)\}')
_FX_TOKEN_RE = re.compile(r'^fx\[([A-Z0-9]+):([^\]]+)\]\.([a-zA-Z_]+)$')
_FX_CAPTURE_RE = re.compile(r'^fx\[([A-Z0-9]+):(\d+)\]\.on_value$')
_LINK_RE = re.compile(r'dashboard/link(\d+)$')


def _decode_relative(v):
	"""Push 2 relative encoder: 0x01-0x3F = +1..+63, 0x7F-0x41 = -1..-63 (P7)."""
	v = int(v)
	if 1 <= v <= 63:
		return v
	if 65 <= v <= 127:
		return v - 128
	return 0


class Surface:
	def __init__(self, ownerComp):
		self.ownerComp = ownerComp
		self.GridMode = 'SESSION'
		self.Bank = 1
		self.FocusTarget = 'LAYER1'
		self.HeldFocusTarget = None
		self.Modifiers = set()
		self.ParamBank = False
		self.EncoderValues = {}
		self.EncoderVelocity = {}
		self.ClipScrollX = 0.0
		self._index = {}
		self._cfg = {}
		self.BuildIndex()
		self.LoadCfg()

	def LoadCfg(self):
		t = self.ownerComp.op('config/cfg_general')
		d = {}
		for r in range(1, t.numRows):
			d[t[r, 'key'].val] = t[r, 'value'].val
		self._cfg = d
		return d

	def Cfg(self, key, default=None, cast=str):
		v = self._cfg.get(key, None)
		return cast(v) if v is not None else default

	def BuildIndex(self):
		t = self.ownerComp.op('config/map_controls')
		idx = {}
		for r in range(1, t.numRows):
			cells = [t[r, c].val for c in range(t.numCols)]
			row = dict(zip(_COLS, cells))
			key = (row['in_type'], int(row['in_number']), row['modifier'], row['grid_mode'])
			idx[key] = row
		self._index = idx
		return len(idx)

	def Resolve(self, in_type, number, modifier, grid_mode):
		mods_to_try = [modifier] if modifier == '' else [modifier, '']
		modes_to_try = [grid_mode] if grid_mode == 'ANY' else [grid_mode, 'ANY']
		for m in mods_to_try:
			for gm in modes_to_try:
				row = self._index.get((in_type, number, m, gm))
				if row is not None:
					return row
		return None

	def ActiveModifier(self):
		if 'SELECT' in self.Modifiers:
			return 'SELECT'
		if 'SHIFT' in self.Modifiers:
			return 'SHIFT'
		return ''

	def SetGridMode(self, mode):
		self.GridMode = mode

	def SetBank(self, bank):
		self.Bank = max(1, min(8, bank))

	def LayerIds(self):
		raw = self.Cfg('layer_ids', '1,2,3')
		return [p.strip() for p in raw.split(',')]

	def ResolveTemplate(self, control_path, target, slot_expr, fx_registry=None, focus_override=None):
		"""Fill {L1}/{L2}/{L3}/{bank*16+n} tokens, and fx[TARGET:slot].field
		tokens once fx_registry is available (Phase 4). focus_override lets a
		caller resolve {FOCUS} against a different target than self.FocusTarget
		for one call -- used by the hold-a-layer-button-then-press-Mute combo
		(Phase 6g), which must not disturb the persistent FocusTarget."""
		if control_path is None or control_path == '':
			return control_path
		l1, l2, l3 = self.LayerIds()
		# Bank is 1-based for the performer ("bank 1"), but the CSV's slot
		# formula (bank*16+n) is 0-based-style -- bank 1 must yield clips 1-16
		# (DESIGN.md 3.3), so bind bank-1 into the eval context, not Bank itself.
		focus_target = focus_override if focus_override is not None else self.FocusTarget
		focus_segment = {'LAYER1': '/layers/%s' % l1, 'LAYER2': '/layers/%s' % l2,
			'LAYER3': '/layers/%s' % l3, 'COMPOSITION': ''}.get(focus_target, '')
		ctx = {'L1': l1, 'L2': l2, 'L3': l3, 'bank': self.Bank - 1, 'FOCUS': focus_segment}
		try:
			if slot_expr:
				ctx['slot'] = eval(slot_expr, {'__builtins__': {}}, ctx)
		except Exception:
			pass

		def _sub(m):
			expr = m.group(1)
			fx_match = _FX_TOKEN_RE.match(expr)
			if fx_match:
				if fx_registry is None:
					return m.group(0)
				fx_target, fx_slot_expr, field = fx_match.groups()
				try:
					fx_slot = eval(fx_slot_expr, {'__builtins__': {}}, ctx)
				except Exception:
					return m.group(0)
				resolved = fx_registry.PathFor(fx_target, fx_slot, field)
				return str(resolved) if resolved is not None else m.group(0)
			try:
				return str(eval(expr, {'__builtins__': {}}, ctx))
			except Exception:
				return m.group(0)

		return _TOKEN_RE.sub(_sub, control_path)

	def LogDryRun(self, row, resolved_path, value):
		log = self.ownerComp.op('logic/dryrun_log')
		if log is None:
			return
		line = '%s  action=%s  transport=%s  path=%s  type=%s  value=%s' % (
			row['id'], row['action'], row['transport'], resolved_path,
			row['value_type'], value)
		log.text = (log.text + '\n' + line) if log.text else line

	def HandleInternal(self, row, raw_value, ext):
		"""State-machine actions that never leave TD. raw_value is the decoded
		MIDI value (0-127 for cc/note, or a relative delta for encoders)."""
		action = row['action']
		pressed = raw_value != 0
		if action == 'modifier_shift':
			(self.Modifiers.add if pressed else self.Modifiers.discard)('SHIFT')
		elif action == 'modifier_select':
			(self.Modifiers.add if pressed else self.Modifiers.discard)('SELECT')
		elif action == 'grid_mode_toggle' and pressed:
			self.SetGridMode('FX' if self.GridMode == 'SESSION' else 'SESSION')
		elif action == 'fx_param_bank_toggle' and pressed:
			self.ParamBank = not self.ParamBank
		elif action == 'clip_bank_prev' and pressed:
			self.SetBank(self.Bank - 1)
		elif action == 'clip_bank_next' and pressed:
			self.SetBank(self.Bank + 1)
		elif action == 'clip_bank_select' and pressed:
			self.SetBank(int(row['slot']))
		elif action == 'surface_panic' and pressed:
			if ext is not None:
				ext.Panic()
		elif action == 'fx_registry_rescan' and pressed:
			if ext is not None and ext.FxRegistry is not None:
				ext.FxRegistry.Rescan()
		elif action == 'push_mode_toggle' and pressed:
			if ext is not None and ext.PushIO is not None:
				ext.PushIO.SetMode('live' if ext.PushIO.PushMode else 'user')
		elif action == 'ui_toggle' and pressed:
			mirror = self.ownerComp.op('ui')
			if mirror is not None:
				mirror.par.display = not mirror.par.display.eval()
		elif action == 'display_toggle' and pressed:
			if ext is not None and ext.Display is not None:
				ext.Display.ToggleMode()
		elif action == 'display_fit_toggle' and pressed:
			if ext is not None and ext.Display is not None:
				ext.Display.ToggleFit()
		elif action == 'display_source_toggle' and pressed:
			if ext is not None and ext.Display is not None:
				ext.Display.ToggleSource()
		elif action == 'fx_capture_on_value' and pressed:
			_m = _FX_CAPTURE_RE.match(row['control_path'])
			if _m and ext is not None and ext.FxRegistry is not None:
				target, slot = _m.group(1), int(_m.group(2))
				current = ext.ResolumeState.CurrentOpacity(target, slot) if ext.ResolumeState else None
				if current is not None:
					ext.FxRegistry.SetOnValue(target, slot, current)

	def OnReceiveMIDI(self, in_type, number, channel, value, ext):
		"""Single entry point from midiin1_callbacks.onReceiveMIDI. Resolves the
		control, updates internal state, and either sends (dry_run=0) or logs
		(dry_run=1) via ext.ResolumeOut."""
		mod = self.ActiveModifier()
		row = self.Resolve(in_type, number, mod, self.GridMode)
		if row is None:
			return None
		if row['action'] == 'reserved' or not row['transport']:
			return None

		if row['action'] in ('fx_opacity_toggle', 'fx_bypass_toggle'):
			if ext is None or ext.FxRegistry is None:
				return row
			try:
				slot = int(eval(row['slot'], {'__builtins__': {}}, {'bank': self.Bank - 1})) if row['slot'] else None
			except Exception:
				slot = None
			if slot is not None and value != 0:
				if row['action'] == 'fx_opacity_toggle':
					ext.FxRegistry.TogglePad(row['target'], slot, ext.ResolumeOut)
				else:
					ext.FxRegistry.ToggleBypass(row['target'], slot, ext.ResolumeOut)
			return row

		if row['transport'] == 'internal':
			decoded = _decode_relative(value) if row['action'] == 'param_relative' else value
			self.HandleInternal(row, decoded, ext)
			resolved_path = row['control_path']
			log_value = decoded
		elif ext is not None and not ext.Armed:
			# Refuse-to-arm gate (DESIGN.md 8): only internal escape hatches
			# (Panic, User release/take, modifiers, mode switch) work unarmed.
			return row
		else:
			if row['action'] == 'param_relative':
				delta = _decode_relative(value)
				step = self.Cfg('encoder_step', 0.005, float)
				fine = self.Cfg('encoder_fine_scale', 0.2, float)
				scale = fine if 'SELECT' in self.Modifiers else 1.0
				cur = self.EncoderValues.get(row['id'], 0.0)
				cur = max(0.0, min(1.0, cur + delta * step * scale))
				self.EncoderValues[row['id']] = cur
				log_value = cur
			elif row['action'] == 'param_absolute':
				log_value = value / 16383.0
			elif row['action'] in ('clip_scroll_prev', 'clip_scroll_next'):
				step = 0.1 if row['action'] == 'clip_scroll_next' else -0.1
				self.ClipScrollX = max(0.0, min(1.0, self.ClipScrollX + step))
				log_value = self.ClipScrollX
			else:
				try:
					log_value = float(row['value'])
				except (ValueError, TypeError):
					log_value = value
			if row['action'] in ('layer_focus', 'comp_focus'):
				self.FocusTarget = row['target']
				# LOWER_1-4 are one-shot triggers everywhere else, but for
				# the hold-a-layer-button-then-press-Mute combo (Phase 6g)
				# they also need a genuine held/released signal -- track it
				# separately from the persistent FocusTarget so releasing
				# the button doesn't change what's focused, only what Mute
				# targets while held.
				if value != 0:
					self.HeldFocusTarget = row['target']
				elif self.HeldFocusTarget == row['target']:
					self.HeldFocusTarget = None
			fx_reg = ext.FxRegistry if ext is not None else None
			if row['action'] == 'comp_bypass_toggle' and self.HeldFocusTarget is not None:
				# Mute, hardware CC61 (DESIGN.md T-row): plain press blacks
				# out the whole composition; holding a layer-select button
				# first redirects it to bypass just that layer instead.
				resolved_path = self.ResolveTemplate(
					'/composition{FOCUS}/bypassed', row['target'], row['slot'], fx_reg,
					focus_override=self.HeldFocusTarget)
			else:
				resolved_path = self.ResolveTemplate(row['control_path'], row['target'], row['slot'], fx_reg)
			if row['action'] in ('deck_select', 'deck_prev', 'deck_next') and ext is not None:
				# R5: deck switch purges inactive-deck clips and destroys their
				# parameter ids -- force a full rebuild, don't wait for the WS
				# composition push (which may not distinguish this from noise).
				if ext.ResolumeState is not None:
					ext.ResolumeState.Clips.clear()
				if ext.FxRegistry is not None:
					run('args[0].Rescan()', ext.FxRegistry, delayFrames=15)

		dry_run = self.Cfg('dry_run', '1') in ('1', 'True', 'true')
		if dry_run:
			self.LogDryRun(row, resolved_path, log_value)
		elif ext is not None and ext.ResolumeOut is not None:
			ext.ResolumeOut.Send(row, resolved_path, log_value)
			if row['action'] == 'param_relative' and ext.ResolumeState is not None:
				# Same staleness problem as clip_connect/column_connect below:
				# DashboardLinks (finding 19) only refreshes on the periodic
				# REST poll (state_poll_s, up to a couple seconds), so an LED
				# driven by a link WE just turned would lag the physical
				# knob. Update it optimistically the instant we send; the
				# next poll reconciles it against Resolume's real value
				# (e.g. if the UI clamps or something else also wrote it).
				_m = _LINK_RE.search(row['control_path'])
				if _m:
					link_target = self.FocusTarget if row['target'] == 'FOCUS' else row['target']
					ext.ResolumeState.DashboardLinks[(link_target, int(_m.group(1)))] = log_value
			if row['action'] == 'column_connect' and ext.ResolumeState is not None:
				# A column fires the SAME slot index in every layer at once
				# (DESIGN.md 3.3: column N == the clip sitting at that T-position
				# in every layer band). Same staleness problem as clip_connect --
				# update all three layers optimistically.
				try:
					new_slot = int(eval(row['slot'], {'__builtins__': {}}, {'bank': self.Bank - 1}))
				except Exception:
					new_slot = None
				if new_slot is not None:
					for lyr in self.LayerIds():
						for (l2, clip_idx), c in ext.ResolumeState.Clips.items():
							if l2 == lyr and clip_idx != new_slot:
								c['connected'] = False
						ext.ResolumeState.Clips[(lyr, new_slot)] = {'connected': True}
			if row['action'] == 'clip_connect' and ext.ResolumeState is not None:
				# ResolumeState only updates from WS composition pushes and the
				# still-stub _applyParameterUpdate (Phase 4.6) -- neither fires for
				# a clip WE just connected, so the LED model goes stale forever
				# after the first press. Update optimistically: connecting a clip
				# in Resolume disconnects whatever else was connected in that layer.
				layer_ids = self.LayerIds()
				_layer_map = {'LAYER1': layer_ids[0], 'LAYER2': layer_ids[1], 'LAYER3': layer_ids[2]}
				target_layer = _layer_map.get(row['target'])
				if target_layer is not None:
					try:
						new_slot = int(eval(row['slot'], {'__builtins__': {}}, {'bank': self.Bank - 1}))
					except Exception:
						new_slot = None
					if new_slot is not None:
						for (lyr, clip_idx), c in ext.ResolumeState.Clips.items():
							if lyr == target_layer and clip_idx != new_slot:
								c['connected'] = False
						ext.ResolumeState.Clips[(target_layer, new_slot)] = {'connected': True}
		return row

dats./project1/PUSH_RESOLUME/logic/mod_fxregi:
"""FxRegistry: discovers effects at runtime, pins them to stable pad slots by
identity (not chain position), and answers fx[TARGET:slot].field lookups for
the surface. Nothing about an effect is ever declared in a file. See
DESIGN.md 4 and PHASE3A_FINDINGS.md (opacity lives in params, not mixer;
display_name not displayName)."""

import csv
import io
import os
import time

_TARGETS = ['COMPOSITION', 'LAYER1', 'LAYER2', 'LAYER3']
_PIN_COLS = ['target', 'slot', 'pin_key', 'last_display_name', 'on_value', 'last_seen_iso', 'notes']


def _find_opacity_id(eff):
	params = eff.get('params', {}) or {}
	if 'Opacity' in params and isinstance(params['Opacity'], dict):
		return params['Opacity'].get('id'), 'params.Opacity'
	for k, v in params.items():
		if isinstance(v, dict) and k.lower() == 'opacity':
			return v.get('id'), 'params.' + k
	mixer = eff.get('mixer', {}) or {}
	for k, v in mixer.items():
		if isinstance(v, dict) and k.lower() == 'opacity':
			return v.get('id'), 'mixer.' + k
	for label, d in (('params', params), ('mixer', mixer)):
		for k, v in d.items():
			if isinstance(v, dict) and v.get('valuetype') == 'ParamRange' and v.get('min') == 0:
				return v.get('id'), label + '.' + k + ' (fallback: first 0-min ParamRange)'
	return None, None


class FxRegistry:
	def __init__(self, ownerComp):
		self.ownerComp = ownerComp
		self.Registry = {}
		self.Pins = {}
		self._slotOf = {}
		self._freedAt = {}
		self._loadPins()

	def Cfg(self, key, default=None, cast=str):
		return self.ownerComp.Surface.Cfg(key, default, cast)

	def _pinsPath(self):
		rel = self.Cfg('fx_pins_file', 'config/fx_pins.csv')
		return os.path.join(project.folder, rel)

	def _loadPins(self):
		path = self._pinsPath()
		if not os.path.exists(path):
			return
		with open(path, 'r', newline='') as f:
			for row in csv.DictReader(f):
				pin_key = row.get('pin_key')
				if not pin_key:
					continue
				slot = int(row['slot'])
				target = row['target']
				self.Pins[pin_key] = row
				self._slotOf[pin_key] = (target, slot)

	def _savePins(self):
		path = self._pinsPath()
		buf = io.StringIO()
		w = csv.DictWriter(buf, fieldnames=_PIN_COLS)
		w.writeheader()
		for pin_key, (target, slot) in self._slotOf.items():
			row = self.Pins.get(pin_key, {})
			w.writerow({
				'target': target, 'slot': slot, 'pin_key': pin_key,
				'last_display_name': row.get('last_display_name', ''),
				'on_value': row.get('on_value', self.Cfg('fx_default_on_value', 1.0, float)),
				'last_seen_iso': row.get('last_seen_iso', ''),
				'notes': row.get('notes', ''),
			})
		with open(path, 'w', newline='') as f:
			f.write(buf.getvalue())

	def _effectsFor(self, comp, target):
		if target == 'COMPOSITION':
			return comp.get('video', {}).get('effects', [])
		layer_ids = self.ownerComp.Surface.LayerIds()
		idx = int(target[-1]) - 1
		if idx >= len(layer_ids):
			return []
		layers = comp.get('layers', [])
		li = int(layer_ids[idx]) - 1
		if li < 0 or li >= len(layers):
			return []
		return layers[li].get('video', {}).get('effects', [])

	def _assignSlot(self, target, pin_key, max_slots):
		if pin_key in self._slotOf:
			return self._slotOf[pin_key][1]
		used = {s for (t, s) in self._slotOf.values() if t == target}
		for slot in range(1, max_slots + 1):
			if slot not in used:
				self._slotOf[pin_key] = (target, slot)
				return slot
		debug('FxRegistry: %s has no free slot (max %d), leaving unassigned' % (target, max_slots))
		return None

	def Rebuild(self, comp):
		max_slots = self.Cfg('fx_slots_per_target', 16, int)
		default_on = self.Cfg('fx_default_on_value', 1.0, float)
		ttl_s = self.Cfg('fx_pin_ttl_s', 300, float)
		now = time.time()
		new_registry = {}
		seen_pins = set()

		for target in _TARGETS:
			effects = self._effectsFor(comp, target)
			name_counts = {}
			for chain_index, eff in enumerate(effects):
				name = eff.get('name', '')
				if name == 'Transform':
					# Resolume auto-inserts Transform as the first entry in every
					# effect chain; it has no real opacity (PHASE3A_FINDINGS.md 4
					# noted this resolves via a wrong params.Scale fallback).
					# Skipping it here shifts every real effect's slot down by
					# one automatically -- no separate offset math needed.
					continue
				name_counts[name] = name_counts.get(name, 0) + 1
				ordinal = name_counts[name]
				pin_key = '%s|%s|%d' % (target, name, ordinal)
				seen_pins.add(pin_key)
				slot = self._assignSlot(target, pin_key, max_slots)
				if slot is None:
					continue
				opacity_id, resolved_via = _find_opacity_id(eff)
				bypassed = eff.get('bypassed', {}) or {}
				on_value = float(self.Pins.get(pin_key, {}).get('on_value', default_on))
				self.Pins[pin_key] = {
					'last_display_name': eff.get('display_name') or eff.get('name'),
					'on_value': on_value,
					'last_seen_iso': time.strftime('%Y-%m-%dT%H:%M:%S'),
					'notes': 'opacity via ' + str(resolved_via) if resolved_via else 'opacity NOT FOUND',
				}
				reg_key = '%s:%d' % (target, slot)
				# TogglePad tracks on/off in _padOn on the registry entry
				# itself. Rebuild() replaces the whole dict every poll
				# (state_poll_s, ~2s) or WS composition push -- without
				# carrying this forward, every rebuild silently forgets
				# which pads are on, so the next press re-sends "on" as a
				# no-op instead of turning off (only the press after that
				# actually flips it). Worse with multiple pads: more time
				# between presses raises the odds a rebuild lands between
				# turning a pad on and trying to turn it off.
				old_entry = self.Registry.get(reg_key)
				new_registry[reg_key] = {
					'target': target, 'slot': slot, 'pin_key': pin_key,
					'chain_index': chain_index, 'effect_id': eff.get('id'),
					'name': name, 'label': eff.get('display_name') or name,
					'opacity_id': opacity_id, 'bypassed_id': bypassed.get('id'),
					'bypassed_value': bypassed.get('value'),
					'on_value': on_value, 'present': True,
					'_padOn': old_entry.get('_padOn', False) if old_entry else False,
				}

		for pin_key in list(self._slotOf.keys()):
			if pin_key not in seen_pins:
				if pin_key not in self._freedAt:
					self._freedAt[pin_key] = now
				elif now - self._freedAt[pin_key] > ttl_s:
					target, slot = self._slotOf.pop(pin_key)
					self.Pins.pop(pin_key, None)
					self._freedAt.pop(pin_key, None)
			else:
				self._freedAt.pop(pin_key, None)

		self.Registry = new_registry
		self._writeMirrorTable()
		self._savePins()
		return len(new_registry)

	def _writeMirrorTable(self):
		t = self.ownerComp.op('config/fx_registry')
		if t is None:
			return
		t.clear()
		t.appendRow(['target', 'slot', 'pin_key', 'effect_id', 'opacity_id',
		             'bypassed_id', 'label', 'on_value', 'state'])
		for key in sorted(self.Registry.keys()):
			e = self.Registry[key]
			state = 'BYPASSED' if e['bypassed_value'] else 'ON'
			t.appendRow([e['target'], e['slot'], e['pin_key'], e['effect_id'],
			             e['opacity_id'], e['bypassed_id'], e['label'],
			             e['on_value'], state])

	def CountsByTarget(self):
		out = {t: 0 for t in _TARGETS}
		for e in self.Registry.values():
			out[e['target']] += 1
		return out

	def PathFor(self, target, slot, field):
		"""fx[TARGET:slot].field -> '/parameter/by-id/{id}' string, or the raw
		on_value float for field=='on_value'. None if unresolved."""
		e = self.Registry.get('%s:%d' % (target, int(slot)))
		if e is None:
			return None
		if field == 'on_value':
			return e['on_value']
		pid = e.get(field)
		if pid is None:
			return None
		return '/parameter/by-id/%s' % pid

	def SetOnValue(self, target, slot, value):
		key = '%s:%d' % (target, int(slot))
		e = self.Registry.get(key)
		if e is None:
			return
		e['on_value'] = value
		pin = self.Pins.get(e['pin_key'])
		if pin is not None:
			pin['on_value'] = value
			self._savePins()

	def TogglePad(self, target, slot, resolume_out):
		"""Simplified gesture (no ramp/hold-momentary yet -- see notes):
		jumps opacity between 0.0 and the slot's on_value."""
		e = self.Registry.get('%s:%d' % (target, slot))
		if e is None or e['opacity_id'] is None or resolume_out is None:
			return
		current_is_on = e.get('_padOn', False)
		new_value = 0.0 if current_is_on else e['on_value']
		e['_padOn'] = not current_is_on
		resolume_out.SendWSById(e['opacity_id'], new_value)

	def ToggleBypass(self, target, slot, resolume_out):
		e = self.Registry.get('%s:%d' % (target, slot))
		if e is None or e['bypassed_id'] is None or resolume_out is None:
			return
		new_value = not bool(e.get('bypassed_value'))
		e['bypassed_value'] = new_value
		resolume_out.SendWSById(e['bypassed_id'], new_value)

	def Rescan(self):
		"""Shift+Stop manual rescan: force a fresh REST read and rebuild."""
		web = self.ownerComp.op('net/web1')
		ip = self.Cfg('resolume_ip', '127.0.0.1')
		port = self.Cfg('resolume_web_port', 8080, int)
		web.request('http://%s:%d/api/v1/composition' % (ip, port), 'GET', timeout=8000)

