"""LedPainter: state -> {(kind, number): palette_index}. Pure function, no
side effects, no MIDI. See DESIGN.md 2.3, 4.4.

Known simplification (honest, not hidden): FX pad state uses the pad's own
last-commanded on/off flag (FxRegistry._padOn) rather than the live
subscribed opacity value, because narrow per-effect WS subscriptions
(DESIGN.md 4.6) are not built yet. Session clip pads collapse Resolume's
0-4 'connected' range to a binary lit/unlit rather than the DIM/MID/FULL
bands map_controls.csv declares."""


def Paint(ext):
	"""Returns {(kind, number): palette_index} for every control this pass can
	resolve. Caller (PushIO via ext) diffs/queues/flushes it."""
	out = {}
	surface = ext.Surface
	pushio = ext.PushIO
	if surface is None or pushio is None:
		return out

	t = surface.ownerComp.op('config/map_controls')
	for r in range(1, t.numRows):
		row = {c: t[r, c].val for c in ['id', 'in_type', 'in_number', 'modifier',
		                                'grid_mode', 'action', 'target', 'slot',
		                                'led_state_source', 'led_palette']}
		if not row['led_palette']:
			continue
		# Every pad has both a SESSION-mode and an FX-mode row. Without this
		# filter, Paint() processed both unconditionally and the later row
		# in file order always won -- overwriting a correct SESSION result
		# with a stale/off FX one regardless of which mode was actually
		# active. grid_mode='ANY' rows (global buttons) always apply.
		if row['grid_mode'] not in ('ANY', surface.GridMode):
			continue
		# Also skip the modifier-specific variant of a pad (SHIFT/SELECT
		# rows) when painting the plain/base LED -- only entries with no
		# modifier or matching the currently-held one represent what's lit.
		if row.get('modifier') and row['modifier'] != surface.ActiveModifier():
			continue
		names = row['led_palette'].split('|')
		result = _resolve(row, names, ext)
		if row['in_type'] not in ('note', 'cc'):
			continue
		if result is None:
			# Backlight default (2026-08-16, now the permanent boot state,
			# not a one-off): every non-grid CC button lights up so it's
			# visible in the dark, even ones with no dynamic state we track
			# (Setup/User/Mix/Clip/Browse/arrows/Octave/Page/Tap Tempo...)
			# and even ones the CSV marks 'reserved' (OFF-only palette) --
			# this deliberately overrides that darkness convention in favor
			# of visibility. Grid pads (note-type) are excluded; they stay
			# governed by their own SESSION/FX state so an unlit pad still
			# means "nothing here".
			if row['in_type'] != 'cc':
				continue
			result = 'WHITE_DIM'
		key = (row['in_type'], int(row['in_number']))
		if isinstance(result, tuple):
			# Blink signal: (dim_name, full_name) -- caller (FullRedraw)
			# passes both to PushIO.SetLed's blink_with.
			a = pushio.PaletteIndex(result[0]) if isinstance(result[0], str) else result[0]
			b = pushio.PaletteIndex(result[1]) if isinstance(result[1], str) else result[1]
			out[key] = (a, b)
		else:
			out[key] = pushio.PaletteIndex(result) if isinstance(result, str) else result
	return out


_UPPER_ROW_ACTIONS = ('layer_clear', 'comp_disconnect_all', 'layer_solo_toggle', 'tempo_resync')


def _resolve(row, names, ext):
	action = row['action']
	surface = ext.Surface

	if action in _UPPER_ROW_ACTIONS and surface.GridMode == 'FX' and ext.ResolumeState is not None:
		# UPPER_1-8 (hw CC103-110) sit directly below ENC_1-8 (DESIGN.md
		# layout); in FX mode those encoders drive the focused target's
		# Dashboard link1-8 (mod_surface.py ResolveTemplate {FOCUS} token),
		# so light the button below each encoder with that link's live
		# value instead of the button's own SESSION-mode action state.
		link_index = int(row['in_number']) - 101
		val = ext.ResolumeState.DashboardLinkValue(surface.FocusTarget, link_index)
		if val is None:
			return names[0]
		if val <= 0.02:
			return names[0]
		if val >= 0.98:
			return names[-1]
		return names[1] if len(names) > 2 else names[-1]

	if action == 'grid_mode_toggle':
		return names[1] if surface.GridMode == 'FX' else names[0]
	if action == 'modifier_shift':
		return names[1] if 'SHIFT' in surface.Modifiers else names[0]
	if action == 'modifier_select':
		return names[1] if 'SELECT' in surface.Modifiers else names[0]

	if action in ('layer_focus', 'comp_focus'):
		return names[1] if surface.FocusTarget == row['target'] else names[0]

	if action == 'fx_opacity_toggle' and ext.FxRegistry is not None:
		try:
			slot = int(eval(row['slot'], {'__builtins__': {}}, {'bank': surface.Bank - 1}))
		except Exception:
			return names[0]
		e = ext.FxRegistry.Registry.get('%s:%d' % (row['target'], slot))
		if e is None:
			return names[0]
		if e.get('bypassed_value'):
			return names[4] if len(names) > 4 else names[0]
		return names[3] if e.get('_padOn') else names[1]

	if action == 'fx_bypass_toggle' and ext.FxRegistry is not None:
		try:
			slot = int(eval(row['slot'], {'__builtins__': {}}, {'bank': surface.Bank - 1}))
		except Exception:
			return names[0]
		e = ext.FxRegistry.Registry.get('%s:%d' % (row['target'], slot))
		if e is None:
			return names[0]
		return names[1] if e.get('bypassed_value') else names[0]

	if action == 'column_connect' and ext.ResolumeState is not None:
		layer_ids = surface.LayerIds()
		ctx = {'bank': surface.Bank - 1}
		try:
			slot = int(eval(row['slot'], {'__builtins__': {}}, ctx))
		except Exception:
			return names[0]
		matched = 0
		for lyr in layer_ids:
			clip = ext.ResolumeState.Clips.get((lyr, slot))
			if clip and clip.get('connected'):
				matched += 1
		if matched == 0:
			return names[0]
		if matched == len(layer_ids):
			return names[-1]
		return names[1] if len(names) > 2 else names[-1]

	if action == 'clip_connect' and ext.ResolumeState is not None:
		layer_ids = surface.LayerIds()
		ctx = {'bank': surface.Bank - 1, 'L1': layer_ids[0], 'L2': layer_ids[1], 'L3': layer_ids[2]}
		_layer_map = {'LAYER1': layer_ids[0], 'LAYER2': layer_ids[1], 'LAYER3': layer_ids[2]}
		target_layer = _layer_map.get(row['target'])
		if target_layer is None:
			return names[0]
		try:
			slot = int(eval(row['slot'], {'__builtins__': {}}, ctx))
		except Exception:
			return names[0]
		clip = ext.ResolumeState.Clips.get((target_layer, slot))
		# Three states, not two: blank (no clip loaded), solid (clip present,
		# idle), blinking (currently playing/connected). 'Empty' comes from
		# Resolume's own clip.connected enum (see PHASE3A_FINDINGS.md); a
		# clip WE optimistically marked connected but never fetched a real
		# state string for defaults to 'Connected' so it still blinks.
		state = clip.get('state') if clip else None
		connected = clip.get('connected') if clip else False
		if clip is None or state == 'Empty':
			return names[0]
		full = names[-1]
		if connected:
			return (names[0], full)  # blink between off and full brightness
		return full  # loaded, idle -- full brightness, solid (not dim)

	return None

