"""ResolumeOut: the single write path for both transports. OSC half is live
(Phase 3); the WS half is a queueing stub until FxRegistry exists (Phase 4).
See DESIGN.md 2.3, 6."""


def _cast(value_type, value):
	if value_type == 'int':
		return int(round(float(value)))
	if value_type == 'bool_as_int':
		return int(bool(value) and value != 0)
	if value_type == 'float':
		return float(value)
	return value


class ResolumeOut:
	def __init__(self, ownerComp):
		self.ownerComp = ownerComp
		self.oscOut = ownerComp.op('net/oscout1')
		self.wsOut = ownerComp.op('net/ws1')
		self._oscCache = {}
		self._oscPending = {}
		self._oscQueue = []
		self._oscQueued = set()
		self._wsPending = {}
		self._wsQueue = []
		self._wsQueued = set()

	def Cfg(self, key, default=None, cast=str):
		t = self.ownerComp.op('config/cfg_general')
		for r in range(1, t.numRows):
			if t[r, 'key'].val == key:
				return cast(t[r, 'value'].val)
		return default

	def Send(self, row, resolved_path, value):
		"""Enqueue one control write. Called from Surface.OnReceiveMIDI. The
		actual dead-band diff and send happen at flush time (FlushOSC/FlushWS),
		so a burst of the same path in one tick coalesces to one message."""
		typed = _cast(row['value_type'], value)
		if row['transport'] == 'osc':
			self._enqueue(self._oscQueue, self._oscQueued, self._oscPending,
			              resolved_path, (typed, row['value_type']))
		elif row['transport'] == 'ws':
			self._enqueue(self._wsQueue, self._wsQueued, self._wsPending,
			              resolved_path, (typed, row['value_type']))
		# 'internal' transport is handled entirely by Surface.HandleInternal.

	@staticmethod
	def _enqueue(queue, queued, pending, key, item):
		if key not in queued:
			queue.append(key)
			queued.add(key)
		pending[key] = item

	def FlushOSC(self, cap=32):
		deadband = self.Cfg('osc_deadband', 0.002, float)
		sent = 0
		while self._oscQueue and sent < cap:
			path = self._oscQueue.pop(0)
			self._oscQueued.discard(path)
			item = self._oscPending.pop(path, None)
			if item is None:
				continue
			value, value_type = item
			cached = self._oscCache.get(path)
			# Dead-band is for CONTINUOUS float streams only (encoders/touch
			# strip) -- DESIGN.md 6. Discrete int/bool triggers (clip_connect,
			# layer_focus, column_connect...) must always re-send even when
			# the value is unchanged: every physical press is a fresh bang,
			# not a state stream. An earlier version of this check also
			# skipped unchanged ints, which silently ate every repeat press
			# of any trigger whose CSV value is a constant (e.g. always 1).
			if value_type == 'float' and cached is not None and abs(value - cached) < deadband:
				continue
			self.oscOut.sendOSC(path, [value], asBundle=True, useNonStandardTypes=False)
			self._oscCache[path] = value
			sent += 1
		return sent

	def FlushWS(self, cap=16):
		"""WS half. Envelope confirmed live against Resolume Arena --
		see PHASE3A_FINDINGS.md 6: {"action":"set","parameter":<path str>,"value":<v>}.
		Any path still containing 'fx[' means FxRegistry has not resolved it
		yet (unknown slot) and is dropped."""
		sent = 0
		while self._wsQueue and sent < cap:
			path = self._wsQueue.pop(0)
			self._wsQueued.discard(path)
			item = self._wsPending.pop(path, None)
			if item is None or 'fx[' in path:
				continue
			value, value_type = item
			self._sendWS(path, value)
			sent += 1
		return sent

	def _sendWS(self, path, value):
		import json
		self.wsOut.sendText(json.dumps({'action': 'set', 'parameter': path, 'value': value}))

	def SendWSById(self, param_id, value):
		"""Direct WS send bypassing the queue -- used by FxRegistry gestures
		(TogglePad/ToggleBypass), which already debounce at the gesture level."""
		self._sendWS('/parameter/by-id/%s' % param_id, value)

"""ResolumeState: ingests WebSocket/REST, holds the raw composition tree plus
a normalised state dict for LedPainter. See DESIGN.md 2.3, 4.5.
"""

import json


class ResolumeState:
	def __init__(self, ownerComp):
		self.ownerComp = ownerComp
		self.Composition = None
		self.Connected = False
		self.Clips = {}
		self.Layers = {}
		self.DashboardLinks = {}
		self.DashboardLinkNames = {}

	def LayerIds(self):
		return self.ownerComp.Surface.LayerIds()

	def IsCompositionMessage(self, msg):
		"""No 'type' field; detected the way Resolume's own Companion module
		does (DESIGN.md 4.5)."""
		return 'type' not in msg and 'columns' in msg and 'layers' in msg

	def OnMessage(self, raw_text, ext):
		try:
			msg = json.loads(raw_text)
		except Exception:
			return
		if isinstance(msg, dict) and self.IsCompositionMessage(msg):
			self.Composition = msg
			self._normaliseFromComposition(msg)
			if ext.FxRegistry is not None:
				ext.FxRegistry.Rebuild(msg)
			return
		mtype = msg.get('type') if isinstance(msg, dict) else None
		if mtype == 'parameter_update':
			self._applyParameterUpdate(msg)

	def _normaliseFromComposition(self, comp):
		layer_ids = self.LayerIds()
		layers = comp.get('layers', [])
		links = {}
		names = {}
		self._extractDashboard('COMPOSITION', comp.get('dashboard', {}), links, names)
		layer_targets = ('LAYER1', 'LAYER2', 'LAYER3')
		for i, lid in enumerate(layer_ids):
			if i >= len(layers):
				continue
			layer = layers[i]
			self.Layers[lid] = {
				'bypassed': layer.get('bypassed', {}).get('value'),
				'solo': layer.get('solo', {}).get('value'),
				'opacity': layer.get('video', {}).get('opacity', {}).get('value'),
			}
			if i < len(layer_targets):
				self._extractDashboard(layer_targets[i], layer.get('dashboard', {}), links, names)
			clips = layer.get('clips', [])
			for ci, clip in enumerate(clips):
				state = clip.get('connected', {}).get('value') if isinstance(clip, dict) else None
				connected = state in ('Connected', 'Connected & previewing')
				self.Clips[(lid, ci + 1)] = {'connected': connected, 'state': state}
		self.DashboardLinks = links
		self.DashboardLinkNames = names

	@staticmethod
	def _extractDashboard(target, dashboard, out, out_names):
		"""dashboard is Resolume's {'Link 1': {...,'value':float}, ...} object,
		present both at composition level and per-layer (confirmed live via
		REST -- both carry exactly Link 1-8, see PHASE3A_FINDINGS.md). Each
		link's view.alternative_name is the user-assigned name shown in
		Resolume's own Dashboard UI (e.g. "Hue Rotate") -- absent if the
		performer never renamed that link (confirmed live 2026-09-09)."""
		for i in range(1, 9):
			link = dashboard.get('Link %d' % i)
			if link is not None:
				out[(target, i)] = link.get('value')
				name = link.get('view', {}).get('alternative_name')
				if name:
					out_names[(target, i)] = name

	def DashboardLinkValue(self, target, link_index):
		"""Live value (0.0-1.0) of a Dashboard link for COMPOSITION or a
		LAYER1/2/3 target, or None if not yet polled."""
		return self.DashboardLinks.get((target, link_index))

	def DashboardLinkName(self, target, link_index):
		"""User-assigned Dashboard link name, or None if the performer never
		renamed it (caller should fall back to 'Link N')."""
		return self.DashboardLinkNames.get((target, link_index))

	def _applyParameterUpdate(self, msg):
		# Narrow-subscription updates (DESIGN.md 4.6) land here in Phase 4b.
